import{_ as t,o,c as s,ag as a}from"./chunks/framework.B7PviQjB.js";const p=JSON.parse('{"title":"Self-hosting","description":"Run Wafflebase on your own infrastructure so your documents, accounts, and files stay on servers you control.","frontmatter":{"title":"Self-hosting","description":"Run Wafflebase on your own infrastructure so your documents, accounts, and files stay on servers you control.","type":"overview"},"headers":[],"relativePath":"developers/self-hosting/index.md","filePath":"developers/self-hosting/index.md"}'),n={name:"developers/self-hosting/index.md"};function r(d,e,i,l,c,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="self-hosting" tabindex="-1">Self-hosting <a class="header-anchor" href="#self-hosting" aria-label="Permalink to &quot;Self-hosting&quot;">​</a></h1><p>Self-hosting runs Wafflebase on your own infrastructure so your documents, accounts, and files stay on servers you control.</p><p>Wafflebase is open source under the Apache-2.0 license. Use self-hosting to:</p><ul><li>Develop and test changes on <code>localhost</code> with the full stack</li><li>Run a private instance for your team on your own domain</li><li>Keep every document, account, and uploaded file inside your network</li></ul><h2 id="what-you-run" tabindex="-1">What you run <a class="header-anchor" href="#what-you-run" aria-label="Permalink to &quot;What you run&quot;">​</a></h2><p>A deployment has five parts. Browsers talk to the backend and to Yorkie directly.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser ──── Frontend (static build) ──── Backend (NestJS, :3000)</span></span>
<span class="line"><span>   │                                            │</span></span>
<span class="line"><span>   │                                      ┌─────┴─────┐</span></span>
<span class="line"><span>   └──────── Yorkie server (:8080) ── PostgreSQL   Blob store (S3)</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    └── auth webhook ──► Backend /internal/yorkie/auth</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Component</th><th>What it does</th></tr></thead><tbody><tr><td>Frontend</td><td>Static bundle. Its backend and Yorkie addresses are fixed at build time</td></tr><tr><td>Backend</td><td>Sign-in, permissions, file storage, datasources, and the REST API</td></tr><tr><td>Yorkie</td><td>Real-time sync of document content between browsers</td></tr><tr><td>PostgreSQL</td><td>Accounts, workspaces, document records, folders, share links, API keys, notifications, and templates</td></tr><tr><td>Blob store</td><td>Uploaded files, PDFs, images, and images embedded in documents</td></tr></tbody></table><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Version</th></tr></thead><tbody><tr><td>Node.js</td><td>22 (the repository&#39;s <code>.nvmrc</code>)</td></tr><tr><td>pnpm</td><td>10.5.2 (<code>corepack enable</code> picks up the pinned version)</td></tr><tr><td>PostgreSQL</td><td>16 is what is built and tested</td></tr><tr><td>Docker Compose</td><td>v2 (<code>docker compose</code>, not <code>docker-compose</code>)</td></tr></tbody></table><p>You also need a GitHub OAuth app for sign-in. Google sign-in is optional.</p><h2 id="where-your-data-lives" tabindex="-1">Where your data lives <a class="header-anchor" href="#where-your-data-lives" aria-label="Permalink to &quot;Where your data lives&quot;">​</a></h2><ul><li><strong>PostgreSQL</strong>: user profiles, workspaces, document records, folders, share links, API keys, notifications, and template listings.</li><li><strong>Yorkie</strong>: document content (cells, text, slides, notes, board elements, comments) and its version history.</li><li><strong>Blob store</strong>: uploaded files and embedded images.</li></ul><p>Back up all three. Nothing is sent to a third party unless you turn it on: Google Analytics (<code>VITE_GA_ID</code>), error tracking (<code>SENTRY_DSN</code>, <code>VITE_SENTRY_DSN</code>), and share-link analytics each stay off until you set them, and the analytics pipeline runs on Kafka and StarRocks services you host yourself.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li><a href="/docs/developers/self-hosting/local-development.html">Run Wafflebase locally</a> with Docker Compose and the dev servers.</li><li><a href="/docs/developers/self-hosting/sign-in.html">Set up sign-in</a> with a GitHub OAuth app, and Google if you want it.</li><li><a href="/docs/developers/self-hosting/deploy.html">Deploy to production</a>: build the backend image and the frontend with your own URLs.</li></ol><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>See</th></tr></thead><tbody><tr><td>Start the full stack on your machine</td><td><a href="/docs/developers/self-hosting/local-development.html">Local development</a></td></tr><tr><td>Look up an environment variable</td><td><a href="/docs/developers/self-hosting/configuration.html">Configuration</a></td></tr><tr><td>Configure GitHub, GitHub Enterprise, or Google sign-in</td><td><a href="/docs/developers/self-hosting/sign-in.html">Sign-in providers</a></td></tr><tr><td>Build, migrate, and run behind TLS</td><td><a href="/docs/developers/self-hosting/deploy.html">Deploy to production</a></td></tr><tr><td>Enforce per-document access at the sync layer</td><td><a href="/docs/developers/self-hosting/deploy.html#turn-on-per-document-access-control">Turn on per-document access control</a></td></tr><tr><td>Configure file and image storage</td><td><a href="/docs/developers/self-hosting/deploy.html#set-up-blob-storage">Set up blob storage</a></td></tr><tr><td>Turn on analytics, lakehouse, error tracking, or the template gallery</td><td><a href="/docs/developers/self-hosting/optional-features.html">Optional features</a></td></tr><tr><td>Fix a startup, sign-in, or upload error</td><td><a href="/docs/developers/self-hosting/troubleshooting.html">Troubleshooting</a></td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/developers/self-hosting/local-development.html">Local development</a> to try it on your machine first.</li><li><a href="/docs/developers/self-hosting/deploy.html">Deploy to production</a> when you are ready for a real domain.</li><li><a href="/docs/developers/cli/">CLI</a> to script your instance once it runs.</li></ul>`,20)])])}const f=t(n,[["render",r]]);export{p as __pageData,f as default};
